def zone_min_max(ind):
    z=zones[(zones.ind==ind)&(zones.h=="3m")].sort_values("zone")
    z=z[z.n_days>=60]
    if len(z)<2: return ("","")
    lo=z.iloc[0]; hi=z.iloc[-1]
    return (f"{lo.fwd_ann:+.1f}% (n={int(lo.n_days)})", f"{hi.fwd_ann:+.1f}% (n={int(hi.n_days)})")
