    rows.append(f"<tr><td class='nm'>{html.escape(NAMES[ind])}<br><span class='sub'>{ind} · {KIND[ind]}</span></td><td class='num'>{W[ind]:.1f}</td><td class='num'>{ic.loc[ind,'ic_3m']:+.2f}</td><td class='num'>{ic.loc[ind,'ic_12m']:+.2f}</td><td class='num'>{lo}</td><td class='num'>{hi}</td><td class='num {'pos' if a[0]>0.02 else 'neg' if a[0]<-0.02 else ''}'>{a[0]:+.3f}<br><span class='sub'>{a[1]:+.2f} / {a[2]:+.2f}</span></td><td><span class='tag {cls}'>{html.escape(v)}</span><div class='cm'>{html.escape(c)}</div></td></tr>")
